tool_input.command:
# Try removing individual files in .sentinel, skip locked ones
$sentinel_path = ".\.sentinel"
$removed_size = 0

if (Test-Path $sentinel_path) {
    Get-ChildItem -Path $sentinel_path -Recurse -Force -ErrorAction SilentlyContinue | Where-Object {-not $_.PSIsContainer} | ForEach-Object {
        try {
            $size = $_.Length
            Remove-Item -Path $_.FullName -Force -ErrorAction Stop
            $removed_size += $size
        } catch {
            # Skip locked files
        }
    }

    # Try to remove empty directories
    Get-ChildItem -Path $sentinel_path -Recurse -Force -ErrorAction SilentlyContinue | Where-Object {$_.PSIsContainer} | Sort-Object -Property FullName -Descending | ForEach-Object {
        try {
            Remove-Item -Path $_.FullName -Force -ErrorAction Stop
        } catch {
            # Skip if not empty or locked
        }
    }
}

$freedMB = [math]::Round($removed_size / 1MB, 2)
Write-Output "Freed from .sentinel: $freedMB MB"

# Final tally
Write-Output "`nCurrent disk usage:"
Get-ChildItem -Path . -Force -ErrorAction SilentlyContinue | Where-Object {$_.PSIsContainer} | ForEach-Object {
    $size = (Get-ChildItem -Path $_.FullName -Recurse -Force -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum).Sum
    $sizeKB = [math]::Round($size / 1KB, 2)
    Write-Output "$($_.Name) : $sizeKB KB"
}
